export function initVideo(){const e=[...document.querySelectorAll(".element-wrapper img")],t=e=>{if("false"===function(e){const t=document.cookie.split("; ");for(let n of t){const[t,o]=n.split("=");if(t===e)return o}return null}("marketing_consent"))return;const t=e.dataset.id,n=e.closest(".element-wrapper"),o=(e=>{const t=document.createElement("iframe");return t.src=`https://www.tiktok.com/embed/${e}`,t.width=325,t.height="100%",t.loading="lazy",t})(t);n.textContent="",n.appendChild(o)};for(let n of e)n.addEventListener("click",(()=>t(n)))}